      { q: "Explain why ceteris paribus is an important assumption in economic models and state one limitation of it.", m: 3, a: "Ceteris paribus holds all other variables constant [1], so economists can isolate the effect of one variable on another (e.g. price on quantity demanded) [1]. Limitation: in the real world other factors change at the same time, so predictions may be inaccurate [1]." },
      { q: "Distinguish between positive and normative statements, using an example of each from the topic of unemployment.", m: 4, a: "Positive: a statement of fact that can be tested against evidence [1], e.g. ‘Unemployment rose from 4% to 6%’ [1]. Normative: a value judgement about what ought to be that cannot be proved by evidence [1], e.g. ‘Unemployment is too high and the government should reduce it’ [1]." }
