            "Income fell $10,000 but tax fell $3,000, so disposable income fell only $7,000 (not $10,000) → consumption falls by less → AD cushioned.",
            "Average tax rate: 11,000/50,000 = 22% → 8,000/40,000 = 20% (progressive).",
